import{_ as e,o as i,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"UC 08 — Admin Management (UC-97 → UC-106)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/08-admin-management.md","filePath":"ba/use-cases/08-admin-management.md"}'),o={name:"ba/use-cases/08-admin-management.md"};function n(a,t,l,d,c,u){return i(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="uc-08-—-admin-management-uc-97-→-uc-106" tabindex="-1">UC 08 — Admin Management (UC-97 → UC-106) <a class="header-anchor" href="#uc-08-—-admin-management-uc-97-→-uc-106" aria-label="Permalink to &quot;UC 08 — Admin Management (UC-97 → UC-106)&quot;">​</a></h1><p>&gt; <a href="./../00-overview.html">&lt;&lt; Về Overview</a> · Nguồn FR: <a href="./../09-admin-management.html">09-admin-management.md</a> &gt; Nguồn UC gốc: <code>Các FR của hệ thống - Use Case.csv</code> &gt; <strong>Toàn bộ actor:</strong> ADMIN — tách biệt hoàn toàn khỏi cấu trúc Agency→Workspace.</p><h2 id="bang-tong-hop" tabindex="-1">Bảng tổng hợp <a class="header-anchor" href="#bang-tong-hop" aria-label="Permalink to &quot;Bảng tổng hợp&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UC ID</th><th>Use Case</th><th>Actor(s)</th><th>Related FR</th></tr></thead><tbody><tr><td>UC-97</td><td>Send System-Wide Notification</td><td>ADMIN</td><td>3.10.1</td></tr><tr><td>UC-98</td><td>View Platform Statistics Overview</td><td>ADMIN</td><td>3.10.2</td></tr><tr><td>UC-99</td><td>Monitor System Health</td><td>ADMIN</td><td>3.10.3</td></tr><tr><td>UC-100</td><td>Review Content Moderation Queue</td><td>ADMIN</td><td>3.10.4</td></tr><tr><td>UC-101</td><td>View User List</td><td>ADMIN</td><td>3.10.6</td></tr><tr><td>UC-102</td><td>Create User</td><td>ADMIN</td><td>3.10.7</td></tr><tr><td>UC-103</td><td>Update User</td><td>ADMIN</td><td>3.10.8</td></tr><tr><td>UC-104</td><td>Deactivate/Disable User</td><td>ADMIN</td><td>3.10.5, 3.10.9</td></tr><tr><td>UC-105</td><td>View Revenue Dashboard</td><td>ADMIN</td><td>3.10.11</td></tr><tr><td>UC-106</td><td>Export PDF Report</td><td>ADMIN</td><td>3.10.12</td></tr></tbody></table><p>&gt; <strong>Ghi chú số hiệu FR:</strong> CSV gốc nhảy từ 3.10.9 sang 3.10.11 (không có 3.10.10) — giữ nguyên, không tự đánh số lại.</p><hr><h2 id="uc-97-—-send-system-wide-notification" tabindex="-1">UC-97 — Send System-Wide Notification <a class="header-anchor" href="#uc-97-—-send-system-wide-notification" aria-label="Permalink to &quot;UC-97 — Send System-Wide Notification&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> Create and send notifications to the entire system, optionally segmented by user group.</li><li><strong>Precondition:</strong> User is ADMIN.</li><li><strong>Main Flow:</strong><ol><li>ADMIN composes a notification, optionally targets a user segment.</li><li>System broadcasts the notification (push/in-app).</li></ol></li></ul><h2 id="uc-98-—-view-platform-statistics-overview" tabindex="-1">UC-98 — View Platform Statistics Overview <a class="header-anchor" href="#uc-98-—-view-platform-statistics-overview" aria-label="Permalink to &quot;UC-98 — View Platform Statistics Overview&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> View an overview dashboard (users, revenue, active agencies) with charts.</li><li><strong>Precondition:</strong> User is ADMIN.</li><li><strong>Main Flow:</strong><ol><li>ADMIN opens the Platform Statistics dashboard.</li><li>System displays charts: user growth, revenue, active Agencies.</li></ol></li></ul><h2 id="uc-99-—-monitor-system-health" tabindex="-1">UC-99 — Monitor System Health <a class="header-anchor" href="#uc-99-—-monitor-system-health" aria-label="Permalink to &quot;UC-99 — Monitor System Health&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> Monitor resource usage (%CPU, %RAM...) and the live status of servers within the microservice system.</li><li><strong>Precondition:</strong> User is ADMIN.</li><li><strong>Main Flow:</strong><ol><li>ADMIN opens System Health dashboard.</li><li>System displays live resource metrics and up/down status per microservice.</li></ol></li></ul><h2 id="uc-100-—-review-content-moderation-queue" tabindex="-1">UC-100 — Review Content Moderation Queue <a class="header-anchor" href="#uc-100-—-review-content-moderation-queue" aria-label="Permalink to &quot;UC-100 — Review Content Moderation Queue&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> View and review content created by Creators that was flagged by the system&#39;s moderation policy.</li><li><strong>Precondition:</strong> At least one content item auto-flagged by Compliance Check (see <a href="./04-content-task-workflow.html">04-content-task-workflow.md</a> UC-72).</li><li><strong>Main Flow:</strong><ol><li>ADMIN opens the Content Moderation Queue.</li><li>Reviews each flagged item, confirms or overturns the system&#39;s automated decision.</li></ol></li><li><strong>Note:</strong> Admin reviews the system&#39;s existing flag decision — not performing moderation from scratch.</li></ul><h2 id="uc-101-—-view-user-list" tabindex="-1">UC-101 — View User List <a class="header-anchor" href="#uc-101-—-view-user-list" aria-label="Permalink to &quot;UC-101 — View User List&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> View the list of users in the system.</li><li><strong>Precondition:</strong> User is ADMIN.</li><li><strong>Main Flow:</strong><ol><li>ADMIN opens User Management.</li><li>System lists all users with search/filter.</li></ol></li></ul><h2 id="uc-102-—-create-user" tabindex="-1">UC-102 — Create User <a class="header-anchor" href="#uc-102-—-create-user" aria-label="Permalink to &quot;UC-102 — Create User&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> Create a new user account in the system.</li><li><strong>Precondition:</strong> User is ADMIN.</li><li><strong>Main Flow:</strong><ol><li>ADMIN fills new user details, submits.</li><li>System creates the account.</li></ol></li></ul><h2 id="uc-103-—-update-user" tabindex="-1">UC-103 — Update User <a class="header-anchor" href="#uc-103-—-update-user" aria-label="Permalink to &quot;UC-103 — Update User&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> Update an existing user&#39;s information.</li><li><strong>Precondition:</strong> Target user exists.</li><li><strong>Main Flow:</strong><ol><li>ADMIN edits user fields, submits.</li><li>System persists changes.</li></ol></li></ul><h2 id="uc-104-—-deactivate-disable-user" tabindex="-1">UC-104 — Deactivate/Disable User <a class="header-anchor" href="#uc-104-—-deactivate-disable-user" aria-label="Permalink to &quot;UC-104 — Deactivate/Disable User&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> Verify, disable, or delete a user account.</li><li><strong>Precondition:</strong> Target user exists.</li><li><strong>Main Flow:</strong><ol><li>ADMIN selects a status action (verify/disable/delete) on the target user.</li><li>System applies the state transition directly.</li></ol></li><li><strong>Business Rule:</strong> Deliberately kept as one combined FR (not split into separate verify/disable/delete FRs) to reduce endpoint count.</li><li><strong>Open Question:</strong> Can an Admin deactivate/delete another Admin? Is there a max Admin count? <strong>[OPEN QUESTION]</strong> — unresolved in source CSV, needs decision before RBAC design finalized for this action.</li></ul><h2 id="uc-105-—-view-revenue-dashboard" tabindex="-1">UC-105 — View Revenue Dashboard <a class="header-anchor" href="#uc-105-—-view-revenue-dashboard" aria-label="Permalink to &quot;UC-105 — View Revenue Dashboard&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> View system revenue generated from subscription plans and credit purchases.</li><li><strong>Precondition:</strong> User is ADMIN.</li><li><strong>Main Flow:</strong><ol><li>ADMIN opens Revenue Dashboard.</li><li>System displays revenue breakdown by Plan tier and AI Credit purchases.</li></ol></li></ul><h2 id="uc-106-—-export-pdf-report" tabindex="-1">UC-106 — Export PDF Report <a class="header-anchor" href="#uc-106-—-export-pdf-report" aria-label="Permalink to &quot;UC-106 — Export PDF Report&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> Export a PDF report for the User Management, Revenue, and other admin pages.</li><li><strong>Precondition:</strong> User is ADMIN, viewing an exportable admin page.</li><li><strong>Main Flow:</strong><ol><li>ADMIN selects Export PDF on the current page.</li><li>System generates and downloads a PDF report of the current data view.</li></ol></li></ul>',26)])])}const m=e(o,[["render",n]]);export{h as __pageData,m as default};
